  "content": "import typing

import tenacity


def my_stop(retry_state: tenacity.RetryCallState) -> bool:
    return True


def my_retry(retry_state: tenacity.RetryCallState) -> bool:
    return False


def my_wait(retry_state: tenacity.RetryCallState) -> float:
    return 0.0


def test_retrying_accepts_callable_callbacks() -> None:
    for attempt in tenacity.Retrying(retry=my_retry, wait=my_wait, stop=my_stop):
        with attempt:
            pass


def test_retrying_accepts_callable_callbacks_with_result() -> None:
    result = tenacity.Retrying(retry=my_retry, wait=my_wait, stop=my_stop)(lambda: 42)
    assert result == 42


def test_retrying_accepts_callable_callbacks_with_exception() -> None:
    import pytest
    with pytest.raises(ValueError):
        tenacity.Retrying(retry=my_retry, wait=my_wait, stop=my_stop)(lambda: (_ for _ in ()).throw(ValueError("test")))
